#!/usr/bin/env python3
"""Generate modules.h embedding Lua sources for host.c.

Usage: embed_modules.py OUT.h name=path [name=path ...]
Each module becomes a byte array; the (name, data, len)
table is in declaration order."""
import sys

def main():
    out_path, pairs = sys.argv[1], sys.argv[2:]
    table = []
    lines = [
        "/* Generated by wasm/lua/embed_modules.py. DO NOT EDIT. */",
        "#ifndef GRPC_DC_MODULES_H",
        "#define GRPC_DC_MODULES_H",
        "#include <stddef.h>",
        "typedef struct { const char *name; const unsigned char *data; size_t len; } EmbeddedModule;",
    ]
    for i, pair in enumerate(pairs):
        name, path = pair.split("=", 1)
        data = open(path, "rb").read()
        table.append(name)
        lines.append(f"static const unsigned char MODULE_{i}[] = {{")
        for j in range(0, len(data), 16):
            lines.append("    " + ", ".join(str(b) for b in data[j:j + 16]) + ",")
        lines.append("};")
    lines.append("static const EmbeddedModule EMBEDDED[] = {")
    for i, name in enumerate(table):
        lines.append(f'    {{ "{name}", MODULE_{i}, sizeof(MODULE_{i}) }},')
    lines.append("};")
    lines.append(f"#define EMBEDDED_COUNT {len(table)}")
    lines.append("#endif")
    open(out_path, "w").write("\n".join(lines) + "\n")

if __name__ == "__main__":
    main()
